        ["Reports"] = "Relatórios",
        ["Dashboards over the OData entity sets with charts, KPIs, tables and filters, aggregated on the server."] = "Painéis sobre os conjuntos de entidades OData com gráficos, KPIs, tabelas e filtros, agregados no servidor.",
        ["For apps whose users want to see their numbers."] = "Para aplicações cujos utilizadores querem ver os seus números.",
