        ["Together with the primary color."] = "Juntamente com a cor primária.",
        ["Accent in buttons and links"] = "Destaque em botões e ligações",
        ["Logo file (svg, png, ...); the CLI copies it into the web client. It shows in the app bar, the browser tab and on the sign-in pages."] = "Ficheiro do logótipo (svg, png, ...); a CLI copia-o para o cliente web. Aparece na barra da aplicação, no separador do browser e nas páginas de início de sessão.",
        ["Always for a real app."] = "Sempre para uma aplicação real.",
        ["One file for app, tab and sign-in"] = "Um ficheiro para a aplicação, o separador e o início de sessão",
        ["SVG scales best"] = "O SVG escala melhor",
        ["Sign-in layout"] = "Esquema do início de sessão",
        ["Layout of the sign-in pages."] = "Esquema das páginas de início de sessão.",
        ["Split for a full-page image or video, Card for a plain look."] = "Dividido para uma imagem ou vídeo de página inteira, Cartão para um visual simples.",
        ["Changeable later on the Themes page"] = "Pode ser alterado mais tarde na página Temas",
        ["A centered card."] = "Um cartão centrado.",
        ["Image or video on one side, the form on the other."] = "Imagem ou vídeo de um lado, o formulário do outro.",
        ["A colored panel next to the form."] = "Um painel colorido junto ao formulário.",
        ["Sign-in media"] = "Multimédia do início de sessão",
        ["Image or video next to the sign-in form: a local file (copied into the web client) or an http(s) address."] = "Imagem ou vídeo junto ao formulário de início de sessão: um ficheiro local (copiado para o cliente web) ou um endereço http(s).",
        ["With the Split or Slide layout."] = "Com o esquema Dividido ou Deslizante.",
