        ["SignInMedia to greet with the sign-in image or video already while loading."] = "SignInMedia para dar as boas-vindas com a imagem ou o vídeo do início de sessão já durante o carregamento.",
        ["Soft moving shapes in the theme's colours."] = "Formas em movimento suave nas cores do tema.",
        ["The image or video of the sign-in pages."] = "A imagem ou o vídeo das páginas de início de sessão.",
        ["The theme's background colour only."] = "Apenas a cor de fundo do tema.",
        [".mp4, .webm, .ogg and .mov play as video"] = ".mp4, .webm, .ogg e .mov são reproduzidos como vídeo",
        ["Large videos slow the first sign-in"] = "Vídeos grandes atrasam o primeiro início de sessão",
        ["Sign-in media side"] = "Lado do multimédia do início de sessão",
        ["Side of the sign-in media."] = "Lado do multimédia do início de sessão.",
        ["To match the media's composition."] = "Para combinar com a composição do multimédia.",
        ["Media left."] = "Multimédia à esquerda.",
        ["Media right."] = "Multimédia à direita.",
        ["Default mapping of generated entities to their DTOs; an entity can choose its own."] = "Mapeamento predefinido das entidades geradas para os seus DTOs; uma entidade pode escolher o seu.",
        ["Mapperly for many or large entities."] = "Mapperly para muitas entidades ou entidades grandes.",
        ["manual: plain code you can read"] = "manual: código simples e legível",
        ["mapperly: compile-time mapper, reports unmapped members"] = "mapperly: mapper em tempo de compilação, assinala membros não mapeados",
        ["manual: one more line per property"] = "manual: mais uma linha por propriedade",
